// テスト対象の機能一覧を定義
// ここを編集して、テスト仕様書を生成したい機能を追加してください
const features = [
  {
    feature_name: 'ユーザーログイン',
    description: 'メールアドレスとパスワードによるログイン機能',
    category: 'Authentication',
    priority: 'High',
    test_cases: [
      { name: '正常ログイン', precondition: '登録済みユーザーが存在する', steps: '1. メールアドレスを入力\n2. パスワードを入力\n3. ログインボタンをクリック', expected: 'ダッシュボードに遷移する', priority: 'High' },
      { name: 'パスワード誤り', precondition: '登録済みユーザーが存在する', steps: '1. メールアドレスを入力\n2. 誤ったパスワードを入力\n3. ログインボタンをクリック', expected: 'エラーメッセージが表示される', priority: 'High' },
      { name: '未入力チェック', precondition: '-', steps: '1. 何も入力せずログインボタンをクリック', expected: 'バリデーションエラーが表示される', priority: 'Medium' },
      { name: 'アカウントロック', precondition: '登録済みユーザーが存在する', steps: '1. 5回連続で誤ったパスワードでログイン試行', expected: 'アカウントがロックされ、ロック通知が表示される', priority: 'High' }
    ]
  },
  {
    feature_name: 'ユーザー登録',
    description: '新規ユーザーアカウント作成機能',
    category: 'Authentication',
    priority: 'High',
    test_cases: [
      { name: '正常登録', precondition: '-', steps: '1. 登録フォームに必要情報を入力\n2. 登録ボタンをクリック', expected: '確認メールが送信され、登録完了メッセージが表示される', priority: 'High' },
      { name: '重複メールアドレス', precondition: '同じメールアドレスで登録済み', steps: '1. 既に登録済みのメールアドレスで登録', expected: 'エラーメッセージが表示される', priority: 'High' },
      { name: 'パスワード強度チェック', precondition: '-', steps: '1. 弱いパスワード(例: 123)で登録', expected: 'パスワード強度に関するエラーメッセージが表示される', priority: 'Medium' }
    ]
  }
];

return features.map(f => ({ json: f }));

const input = $input.first().json;
const featureName = input.feature_name;
const description = input.description || '';
const category = input.category || 'Functional';
const priority = input.priority || 'Medium';
const testCases = input.test_cases || [];

const now = new Date();
const dateStr = now.toISOString().split('T')[0];

const testCaseRows = testCases.map((tc, i) => {
  const id = String(i + 1).padStart(3, '0');
  return `| TC-${id} | ${tc.name} | ${tc.precondition || '-'} | ${tc.steps} | ${tc.expected} | ${tc.priority || priority} | - |`;
}).join('\n');

const markdown = `# テスト仕様書: ${featureName}

## 基本情報

| 項目 | 内容 |
|------|------|
| 機能名 | ${featureName} |
| 作成日 | ${dateStr} |
| カテゴリ | ${category} |
| 優先度 | ${priority} |

## 機能概要

${description}

## テスト環境

| 項目 | 内容 |
|------|------|
| OS | - |
| ブラウザ | - |
| テストサーバー | - |
| テストデータ | - |

## 前提条件

- (前提条件を記載)

## テストケース

| ID | テスト名 | 前提条件 | 手順 | 期待結果 | 優先度 | 結果 |
|----|----------|----------|------|----------|--------|------|
${testCaseRows}

## テスト結果サマリ

| 項目 | 件数 |
|------|------|
| 総テストケース数 | ${testCases.length} |
| 成功 | - |
| 失敗 | - |
| 未実施 | ${testCases.length} |

## 備考

- 
`;

return [{ json: { feature_name: featureName, markdown, date: dateStr } }];

const items = $input.all();
const results = [];

for (const item of items) {
  const { feature_name, markdown, date } = item.json;
  results.push({
    json: {
      feature_name,
      date,
      markdown,
      message: `テスト仕様書を生成しました: ${feature_name}`
    }
  });
}

return results;
